// ─────────────────────────────────────────────────────────────────────────────
// PARSE LEAD FILES
// Reads every file uploaded through the form and turns it into lead rows.
// Supports the files Facebook Leads Center gives you:
//   • .xls  → really an XML spreadsheet (SpreadsheetML 2003)
//   • .csv  → UTF-16 or UTF-8, tab- or comma-separated (phones like "p:+9477…")
// Output: ONE item → { leads, files, problems, formNames }
// ─────────────────────────────────────────────────────────────────────────────

const input = $input.first();
const binaries = input.binary || {};

const leads = [];
const files = [];
const problems = [];

// ---------- helpers ----------
function decodeXml(s) {
  return s.replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos);/gi, (m, e) => {
    const l = e.toLowerCase();
    if (l === 'amp') return '&';
    if (l === 'lt') return '<';
    if (l === 'gt') return '>';
    if (l === 'quot') return '"';
    if (l === 'apos') return "'";
    const code = l[1] === 'x' ? parseInt(l.slice(2), 16) : parseInt(l.slice(1), 10);
    return Number.isFinite(code) ? String.fromCodePoint(code) : m;
  });
}

function decodeText(buf) {
  if (buf[0] === 0xff && buf[1] === 0xfe) return buf.slice(2).toString('utf16le');
  if (buf[0] === 0xfe && buf[1] === 0xff) {
    const b = Buffer.from(buf.slice(2, buf.length - ((buf.length - 2) % 2)));
    b.swap16();
    return b.toString('utf16le');
  }
  if (buf[0] === 0xef && buf[1] === 0xbb && buf[2] === 0xbf) return buf.slice(3).toString('utf8');
  // UTF-16 LE without a BOM → lots of 0x00 bytes in odd positions
  let zeros = 0;
  const n = Math.min(buf.length, 400);
  for (let i = 1; i < n; i += 2) if (buf[i] === 0) zeros++;
  if (n > 10 && zeros > n / 4) return buf.toString('utf16le');
  return buf.toString('utf8');
}

// SpreadsheetML (Facebook .xls) → array of sheets, each an array of rows (arrays of strings)
function parseSpreadsheetML(xml) {
  const sheets = xml.match(/<(?:ss:)?Worksheet\b[\s\S]*?<\/(?:ss:)?Worksheet>/g) || [xml];
  return sheets.map((sheet) => {
    const out = [];
    const rowRe = /<(?:ss:)?Row\b[^>]*?(?:\/>|>([\s\S]*?)<\/(?:ss:)?Row>)/g;
    let rm;
    while ((rm = rowRe.exec(sheet))) {
      const cells = [];
      const cellRe = /<(?:ss:)?Cell\b([^>]*?)(?:\/>|>([\s\S]*?)<\/(?:ss:)?Cell>)/g;
      let cm;
      while ((cm = cellRe.exec(rm[1] || ''))) {
        const idx = /(?:ss:)?Index="(\d+)"/.exec(cm[1]);
        if (idx) while (cells.length < Number(idx[1]) - 1) cells.push('');
        const dm = /<(?:ss:)?Data\b[^>]*>([\s\S]*?)<\/(?:ss:)?Data>/.exec(cm[2] || '');
        cells.push(dm ? decodeXml(dm[1].replace(/<[^>]+>/g, '')) : '');
      }
      out.push(cells);
    }
    return out;
  });
}

// CSV / TSV → [rows]
function parseDelimited(text) {
  const firstLine = text.split(/\r?\n/, 1)[0] || '';
  const count = (ch) => firstLine.split(ch).length - 1;
  const d = ['\t', ',', ';'].sort((a, b) => count(b) - count(a))[0];
  const rows = [];
  let row = [];
  let field = '';
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else quoted = false;
      } else field += c;
    } else if (c === '"' && field === '') quoted = true;
    else if (c === d) { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); rows.push(row); row = []; field = '';
    } else field += c;
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row); }
  return [rows];
}

const normHeader = (h) =>
  String(h ?? '').replace(/^\uFEFF/, '').trim().toLowerCase().replace(/[\s\-]+/g, '_');

function sheetToObjects(rows) {
  // header = first row (within the first 10) that looks like a FB leads header
  const hIdx = rows.slice(0, 10).findIndex((r) =>
    r.map(normHeader).some((h) => ['phone_number', 'full_name', 'form_name', 'street_address'].includes(h)),
  );
  if (hIdx === -1) return null;
  const header = rows[hIdx].map(normHeader);
  const objs = [];
  for (const r of rows.slice(hIdx + 1)) {
    if (!r.some((v) => String(v ?? '').trim() !== '')) continue; // blank row
    const o = {};
    header.forEach((h, i) => { if (h) o[h] = String(r[i] ?? '').trim(); });
    objs.push(o);
  }
  return objs;
}

const pick = (o, ...keys) => {
  for (const k of keys) if (o[k] != null && String(o[k]).trim() !== '') return String(o[k]).trim();
  return '';
};

// ---------- main ----------
const keys = Object.keys(binaries);
if (keys.length === 0) problems.push('No files were uploaded.');

for (const key of keys) {
  const meta = binaries[key] || {};
  const fileName = meta.fileName || key;
  try {
    let buf = await this.helpers.getBinaryDataBuffer(0, key);
    if (!Buffer.isBuffer(buf)) buf = Buffer.from(buf && buf.data ? buf.data : buf);

    if (buf[0] === 0x50 && buf[1] === 0x4b) {
      throw new Error('this is an .xlsx file. Upload the original .xls or .csv exactly as downloaded from Facebook (or re-save it as "CSV UTF-8").');
    }
    if (buf[0] === 0xd0 && buf[1] === 0xcf) {
      throw new Error('this is an old binary Excel file. Upload the original .xls or .csv exactly as downloaded from Facebook (or re-save it as "CSV UTF-8").');
    }

    const text = decodeText(buf);
    const isXml = /<(?:ss:)?Workbook[\s>]|urn:schemas-microsoft-com:office:spreadsheet/.test(text.slice(0, 5000));
    const sheets = isXml ? parseSpreadsheetML(text) : parseDelimited(text);

    let found = 0;
    let headerSeen = false;
    // product name fallback from FB file name: "<Form_Name>_Leads_<from>_<to>.xls"
    const formFromFile = fileName.replace(/\.[^.]+$/, '').replace(/_Leads_.*$/i, '').replace(/_/g, ' ').trim();

    for (const rows of sheets) {
      const objs = sheetToObjects(rows);
      if (!objs) continue;
      headerSeen = true;
      for (const o of objs) {
        const lead = {
          lead_id: pick(o, 'id', 'lead_id').replace(/^l:/, ''),
          created_time: pick(o, 'created_time'),
          form_name: pick(o, 'form_name', 'form') || formFromFile,
          name: pick(o, 'full_name', 'name') || [pick(o, 'first_name'), pick(o, 'last_name')].filter(Boolean).join(' '),
          address: pick(o, 'street_address', 'address', 'full_address'),
          phone_number: pick(o, 'phone_number', 'phone', 'mobile_number'),
          work_phone_number: pick(o, 'work_phone_number', 'work_phone'),
          file: fileName,
        };
        if (!lead.name && !lead.address && !lead.phone_number) continue;
        leads.push(lead);
        found++;
      }
    }
    if (!headerSeen) throw new Error('could not find the lead columns (full_name, street_address, phone_number…).');
    files.push({ file: fileName, leads: found });
  } catch (err) {
    problems.push(`${fileName}: ${err.message}`);
  }
}

// ---------- distinct form names for the product search ----------
// "Kinoki Detox Foot Pads - Copy 2" → "Kinoki Detox Foot Pads"; drop control chars and "$"
const cleanForm = (s) =>
  String(s ?? '')
    .replace(/[\u0000-\u001f\u007f$]/g, ' ')
    .replace(/(\s*[-–_]?\s*\bcopy\b(\s*\d+)?)+\s*$/i, '')
    .replace(/\s+/g, ' ')
    .trim();
for (const lead of leads) lead.form_key = cleanForm(lead.form_name);
const formNames = [...new Set(leads.map((l) => l.form_key).filter(Boolean))];

return [{ json: { leads, files, problems, formNames } }];

// ─────────────────────────────────────────────────────────────────────────────
// BUILD COURIER CSV
// Input  : every row of the "Products" Google Sheet (from "Read Products Sheet")
// Leads  : from "Parse Lead Files"
// Does   : the same word search the old Supabase ILIKE query did, then builds
//          name,address,tp_1,tp_2,price,qty,item_code,delivery
//          file name yyyy_MM_dd(<orders>).csv   e.g. 2026_10_20(56).csv
// ─────────────────────────────────────────────────────────────────────────────

// ---- settings ----
const TIMEZONE = 'Asia/Colombo';
const QTY = 1;
const MIN_FORM_COVERAGE = 0.5;    // at least half of the form name's words must be found in the product (name, id or aliases)
                                  // the best-scoring product then wins; only a real tie is refused
const DEDUPE_BY_LEAD_ID = true;   // same FB lead in two uploaded files → keep once
// ------------------

const parsed = $('Parse Lead Files').first().json;
const leads = parsed.leads || [];
const problems = [...(parsed.problems || [])];

const htmlEsc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// ---------- read the Products sheet ----------
// Headers are matched loosely: "product_ID_Feeder", "Product ID Feeder", "product id feeder" all work.
const normKey = (h) => String(h ?? '').replace(/^\uFEFF/, '').trim().toLowerCase().replace(/[\s\-]+/g, '_');
const cell = (row, ...names) => {
  for (const n of names) {
    const v = row[n];
    if (v != null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};
// "Rs. 1,990.00" → "1990"   (keeps the text as-is if it isn't a number)
const money = (v) => {
  const s = String(v ?? '').trim();
  if (s === '') return '';
  const n = Number(s.replace(/rs\.?|lkr|,|\s/gi, ''));
  return Number.isFinite(n) ? String(n) : s;
};
const isActive = (v) => !/^(false|no|n|0|inactive|off)$/i.test(String(v ?? '').trim()); // blank = active

// same tokenising as the old SQL: "Ayora Gastric Care 30Tablets" → ayora, gastric, care, tablet
const STOP_FORM = new Set(['copy', 'the', 'and', 'for', 'with', 'new', 'form', 'lead', 'leads']);
const STOP_PRODUCT = new Set(['the', 'and', 'for', 'with']);
function words(text, stop) {
  const t = String(text ?? '')
    .replace(/(?<=[0-9])(?=\p{L})/gu, ' ')
    .replace(/(?<=\p{L})(?=[0-9])/gu, ' ')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .toLowerCase();
  const out = new Set();
  for (const w of t.split(/\s+/)) {
    if (w.length < 3 || /^[0-9]+$/.test(w) || stop.has(w)) continue;
    out.add(w.length > 4 ? w.replace(/s$/, '') : w);
  }
  return [...out];
}
const numbers = (text) => [...new Set((String(text ?? '').match(/[0-9]+/g) || []).map((n) => n.replace(/^0+/, '')))];

const products = [];
let rowNo = 1;
for (const { json: raw } of $input.all()) {
  rowNo++;
  if (!raw || typeof raw !== 'object') continue;
  const r = {};
  for (const [k, v] of Object.entries(raw)) r[normKey(k)] = v;
  const product_name = cell(r, 'product_name', 'name', 'product');
  const product_id = cell(r, 'product_id', 'id');
  if (!product_name && !product_id) continue; // blank row
  const aliasesRaw = cell(r, 'aliases', 'alias');
  products.push({
    row: r.row_number ?? rowNo,
    product_id,
    product_name,
    price: money(cell(r, 'price')),
    delivery_fee: money(cell(r, 'delivery_fee', 'delivery')),
    item_code: cell(r, 'product_id_feeder', 'item_code', 'feeder_id').replace(/\.0+$/, ''),
    active: isActive(r.active),
    aliases: aliasesRaw.toLowerCase(),
    alias_list: aliasesRaw
      .split(/[,;|\n\r]/)
      .map((a) => a.replace(/^[\s"'\[\]]+|[\s"'\[\]]+$/g, '').toLowerCase())
      .filter(Boolean),
    // searched text = product name + product id + aliases
    haystack: (product_name + ' ' + product_id.replace(/_/g, ' ') + ' ' + aliasesRaw).toLowerCase(),
    // the product name and every alias are scored on their own; the best one counts
    phrases: [product_name, ...aliasesRaw.split(/[,;|\n\r]/)]
      .map((t) => words(t, STOP_PRODUCT))
      .filter((w) => w.length),
    nums: numbers(product_name),
  });
}
if (products.length === 0) problems.push('The Products Google Sheet is empty or could not be read (check the sheet name and the header row).');

// ---------- the search (same rules as the old ILIKE query) ----------
const round3 = (x) => Math.round(x * 1000) / 1000;
function rankProducts(formName) {
  const form = formName.toLowerCase();
  const fWords = words(formName, STOP_FORM);
  const fNums = new Set(numbers(formName));
  const list = [];
  for (const p of products) {
    const aliasHit = p.alias_list.includes(form) || (form.length >= 12 && p.aliases.includes(form));
    const wordHit = fWords.some((w) => p.haystack.includes(w));
    if (!aliasHit && !wordHit) continue;
    const exact = aliasHit || p.product_name.toLowerCase() === form;
    const form_hits = fWords.filter((w) => p.haystack.includes(w)).length;
    const fc = round3(form_hits / Math.max(fWords.length, 1));
    // how much of the product name (or its best alias) appears in the form name
    const pc = round3(Math.max(0, ...p.phrases.map((ws) => ws.filter((w) => form.includes(w)).length / ws.length)));
    const nums = p.nums.reduce((s, n) => s + (fNums.has(n) ? 1 : -1), 0); // +1 shared pack size, -1 different
    list.push({ ...p, exact, fc, pc, score: round3(fc + pc), nums, form_hits });
  }
  list.sort((a, b) =>
    (b.exact - a.exact) ||
    (b.score - a.score) ||
    (b.nums - a.nums) ||
    (b.form_hits - a.form_hits) ||
    (b.active - a.active) ||
    (a.product_name.length - b.product_name.length) ||
    a.product_id.localeCompare(b.product_id));
  return list;
}

const accepted = (c) => c && (c.exact || c.fc >= MIN_FORM_COVERAGE);

const decisions = new Map();
function decide(formKey) {
  if (decisions.has(formKey)) return decisions.get(formKey);
  const list = formKey ? rankProducts(formKey) : [];
  const [top, second] = list;
  // equally good = same exact flag, same score, same number match, same active flag
  const sameAsTop = (c) => c.exact === top.exact && Math.abs(c.score - top.score) < 0.001 && c.nums === top.nums && c.active === top.active;
  let d;
  if (!top) d = { status: 'none' };
  else if (!accepted(top)) d = { status: 'weak', closest: top };
  else if (second && accepted(second) && sameAsTop(second)) d = { status: 'tie', options: list.filter(sameAsTop).slice(0, 5) };
  else d = { status: 'ok', product: top };
  decisions.set(formKey, d);
  return d;
}

// ---------- phone → 07XXXXXXXX (landlines → 0XXXXXXXXX) ----------
function toLocal(raw) {
  const d = String(raw ?? '').replace(/\D/g, '');   // drops "+", "p:", spaces, dashes
  if (d.length < 9) return '';
  const local = '0' + d.slice(-9);                    // last 9 digits = SL number without the 0
  return /^0[1-9]\d{8}$/.test(local) ? local : '';
}

// ---------- build rows ----------
const rows = [];
const failed = new Map();       // formKey → { d, count }
const incomplete = new Map();   // product_name → { row, missing columns }
const matchedCount = new Map(); // "form → product" → orders
const seen = new Set();
let duplicates = 0;

for (const lead of products.length ? leads : []) {
  if (DEDUPE_BY_LEAD_ID && lead.lead_id) {
    if (seen.has(lead.lead_id)) { duplicates++; continue; }
    seen.add(lead.lead_id);
  }

  const key = lead.form_key || lead.form_name || '';
  const d = decide(key);
  if (d.status !== 'ok') {
    const f = failed.get(key) || { d, count: 0 };
    f.count++;
    failed.set(key, f);
    continue;
  }

  const p = d.product;
  const missing = ['price', 'item_code', 'delivery_fee'].filter((k) => String(p[k] ?? '').trim() === '');
  if (missing.length) { incomplete.set(p.product_name, { row: p.row, missing }); continue; }

  const tp1 = toLocal(lead.phone_number) || toLocal(lead.work_phone_number) || String(lead.phone_number || '').replace(/\D/g, '');
  const tp2 = toLocal(lead.work_phone_number) || tp1;

  rows.push({
    name: String(lead.name || '').trim(),
    address: String(lead.address || '').replace(/\s*[\r\n]+\s*/g, ', ').trim(),
    tp_1: tp1,
    tp_2: tp2,
    price: p.price,
    qty: QTY,
    item_code: p.item_code,
    delivery: p.delivery_fee,
  });
  const label = `${key} → ${p.product_name}`;
  matchedCount.set(label, (matchedCount.get(label) || 0) + 1);
}

// ---------- problems → show them on the form instead of a wrong file ----------
const aliasHint = (form) =>
  `Fix: in the Products Google Sheet add <b>${htmlEsc(form)}</b> to the <code>aliases</code> column of the correct product (comma-separated), then upload again.`;
for (const [form, { d, count }] of failed) {
  const head = `Form <b>"${htmlEsc(form)}"</b> (${count} lead${count > 1 ? 's' : ''}): `;
  if (d.status === 'none') problems.push(head + `no product found. ${aliasHint(form)}`);
  if (d.status === 'weak') problems.push(head + `no confident match — closest is "${htmlEsc(d.closest.product_name)}" (sheet row ${d.closest.row}). ${aliasHint(form)}`);
  if (d.status === 'tie') problems.push(head + `matches several products equally (${d.options.map((c) => `"${htmlEsc(c.product_name)}"`).join(', ')}). ${aliasHint(form)}`);
}
for (const [name, { row, missing }] of incomplete) {
  problems.push(`Product <b>"${htmlEsc(name)}"</b> (sheet row ${row}) is missing ${missing.map((c) => `<code>${c === 'item_code' ? 'product_ID_Feeder' : c}</code>`).join(', ')} in the Products Google Sheet.`);
}
if (problems.length === 0 && rows.length === 0) problems.push('No leads were found in the uploaded file(s).');

if (problems.length) {
  const html = `<h2>Courier file was NOT created</h2><ul>${problems.map((p) => `<li style="margin-bottom:8px">${p}</li>`).join('')}</ul>`;
  return [{ json: { ok: false, html, problems } }];
}

// ---------- CSV (UTF-8 BOM + CRLF, same as the courier sample) ----------
const HEADER = ['name', 'address', 'tp_1', 'tp_2', 'price', 'qty', 'item_code', 'delivery'];
const esc = (v) => {
  const s = v == null ? '' : String(v);
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};
const csv = '\uFEFF' + [HEADER, ...rows.map((r) => HEADER.map((h) => r[h]))]
  .map((r) => r.map(esc).join(','))
  .join('\r\n');

const fileName = `${$now.setZone(TIMEZONE).toFormat('yyyy_MM_dd')}(${rows.length}).csv`;
const fileCount = (parsed.files || []).length;
const summary =
  `${rows.length} orders from ${fileCount} file${fileCount === 1 ? '' : 's'}` +
  (duplicates ? ` · ${duplicates} duplicate lead${duplicates > 1 ? 's' : ''} skipped` : '') +
  `<br>` +
  [...matchedCount].map(([label, n]) => `${htmlEsc(label)} (${n})`).join('<br>');

return [{
  json: { ok: true, fileName, orders: rows.length, duplicates, matches: Object.fromEntries(matchedCount), summary },
  binary: {
    data: {
      data: Buffer.from(csv, 'utf8').toString('base64'),
      mimeType: 'text/csv',
      fileName,
      fileExtension: 'csv',
    },
  },
}];

// Only feeder.retexia.com may call this webhook: X-Retexia-Key = FEEDER_N8N_KEY on the panel (Vercel).
const KEY = 'EDIT: the same value as FEEDER_N8N_KEY in the Retexia panels (Vercel)';
const item = $input.first();
const given = String((item.json.headers || {})['x-retexia-key'] || '');
if (KEY.startsWith('EDIT') || given !== KEY) throw new Error('Unauthorized: wrong or missing X-Retexia-Key.');
if (!item.binary || !Object.keys(item.binary).length) throw new Error('No lead files were sent.');
// The files go on to Parse Lead Files exactly like a form upload.
return [{ json: {}, binary: item.binary }];
